class Solution {
public:
    int countPalindromicSubsequence(string s) {
        int n = s.size();
        int first[26], last[26];
        for (int i = 0; i < 26; i++) {
            first[i] = -1;
            last[i] = -1;
        }
        for (int i = 0; i < n; i++) {
            int c = s[i] - 'a';
            if (first[c] == -1) first[c] = i;
            last[c] = i;
        }
        int ans = 0;
        for (int c = 0; c < 26; c++) {
            if (first[c] == -1 || first[c] == last[c]) continue;
            bool seen[26] = {false};
            for (int i = first[c] + 1; i < last[c]; i++) {
                seen[s[i] - 'a'] = true;
            }
            for (int y = 0; y < 26; y++) {
                if (seen[y]) ans++;
            }
        }
        return ans;
    }
};
